  });

  group('E3 — malformed ids skip resolution', () {
    test('every action answers the shortest error', () async {
      for (final id in ['sh-99', 'garbage', '']) {
        await expectLater(
          tool.execute(_args('output', id: id), null, null),
          throwsA(isA<StateError>()),
        );
        await expectLater(
